export function installPhysicsModuleStubs(implementedTypes, Component, report) {
  reportUse = report;
  Object.setPrototypeOf(PhysicsStubComponent.prototype, Component.prototype);
  for (const [name, Type] of Object.entries(PhysicsUnsupportedComponents))
    Type.__unityUnsupportedPhysicsType = Object.entries(PhysicsUnsupportedTypeNames)
      .find(([, value]) => value === Type)?.[0] ?? `UnityEngine.${name}`;
  const types = { ...PhysicsUnsupportedTypes, ...implementedTypes };
  for (const [typeName, kind, name, isStatic, fullType] of members) {
    const target = isStatic ? types[typeName] : types[typeName]?.prototype;
    if (!target || name in target) continue;
    const api = `${fullType}.${name}`;
    const fallback = /^(GetAll|Overlap|RaycastAll|BoxCastAll|SphereCastAll|CapsuleCastAll)/.test(name) ? []
      : /^(Raycast|Linecast|BoxCast|SphereCast|CapsuleCast|Is|Has|Check|Compute|Set|Ignore)/.test(name) ? false : null;
    if (kind === 'method') Object.defineProperty(target, name, {
      value() { return reportUse(api, fallback); }, configurable: true });
    else if (!(typeName in implementedTypes)) Object.defineProperty(target, name, {
      get() { return reportUse(api, fallback); },
      set() { reportUse(api); }, configurable: true });
  }
}
